public class InnerHarnessHarnessHookFactory(Action<Humidifier.BedrockAgentCore.HarnessTypes.HarnessHook> factoryAction = null) : SubResourceFactory<Humidifier.BedrockAgentCore.HarnessTypes.HarnessHook>
{

    internal InnerHarnessHarnessAfterToolCallHookFactory AfterToolCallFactory { get; set; }

    internal InnerHarnessHarnessBeforeToolCallHookFactory BeforeToolCallFactory { get; set; }

    internal InnerHarnessHarnessAfterInvocationHookFactory AfterInvocationFactory { get; set; }

    internal InnerHarnessHarnessBeforeInvocationHookFactory BeforeInvocationFactory { get; set; }

    protected override Humidifier.BedrockAgentCore.HarnessTypes.HarnessHook Create()
    {
        var harnessHookResult = CreateHarnessHook();
        factoryAction?.Invoke(harnessHookResult);

        return harnessHookResult;
    }

    private Humidifier.BedrockAgentCore.HarnessTypes.HarnessHook CreateHarnessHook()
    {
        var harnessHookResult = new Humidifier.BedrockAgentCore.HarnessTypes.HarnessHook();

        return harnessHookResult;
    }
    public override void CreateChildren(Humidifier.BedrockAgentCore.HarnessTypes.HarnessHook result)
    {
        base.CreateChildren(result);

        result.AfterToolCall ??= AfterToolCallFactory?.Build();
        result.BeforeToolCall ??= BeforeToolCallFactory?.Build();
        result.AfterInvocation ??= AfterInvocationFactory?.Build();
        result.BeforeInvocation ??= BeforeInvocationFactory?.Build();
    }

} // End Of Class

